create table wksp_dtesc.sgt_eventos_fo (
    id             number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    fo_id          number,
    tipo_evento    varchar2(50 byte),
    tipo_falla     varchar2(50 byte),
    estado         varchar2(50 byte),
    criticidad     varchar2(50 byte),
    lon            number,
    lat            number,
    fecha_inicio   date,
    fecha_fin      date,
    creado_por     varchar2(255 byte),
    creado_el      date,
    modificado_por varchar2(255 byte),
    modificado_el  date,
    comentarios    clob
);

alter table wksp_dtesc.sgt_eventos_fo add primary key ( id )
    using index enable;


